package com.arqly.backend.entity;
import jakarta.persistence.*;
@Entity @Table(name="notification_preferences",uniqueConstraints=@UniqueConstraint(name="uk_notification_preference",columnNames={"tenant_user_id","category"}))
public class NotificationPreference extends BaseEntity { @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="tenant_user_id",nullable=false) private TenantUser user; @Enumerated(EnumType.STRING) @Column(nullable=false) private NotificationCategory category; @Column(nullable=false) private boolean inAppEnabled=true; @Column(nullable=false) private boolean emailEnabled=false; public TenantUser getUser(){return user;}public void setUser(TenantUser v){user=v;}public NotificationCategory getCategory(){return category;}public void setCategory(NotificationCategory v){category=v;}public boolean isInAppEnabled(){return inAppEnabled;}public void setInAppEnabled(boolean v){inAppEnabled=v;}public boolean isEmailEnabled(){return emailEnabled;}public void setEmailEnabled(boolean v){emailEnabled=v;} }
